import { defineConfig } from "vite";

// Bundles the CLI into one dependency-free file that is committed, so
// `npx github:craigmcn/colours#<tag>` or a raw download needs no build step
// and a tag pins the exact bytes. CI fails if the committed copy is stale.
export default defineConfig({
  publicDir: false,
  build: {
    ssr: "cli/main.ts",
    outDir: "bin",
    emptyOutDir: true,
    minify: false,
    target: "node20",
    rollupOptions: {
      output: {
        format: "es",
        entryFileNames: "colours-tokens.mjs",
        banner:
          "#!/usr/bin/env node\n// Generated by `yarn build:cli` from src/cli and src/utils. Do not edit.",
      },
    },
  },
  ssr: { noExternal: true },
});
